{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C01"],
      "claim": "U-47700, the closest analogue sharing the cyclohexane-dichlorophenyl amide scaffold, was detected in zebrafish brain after 20-min exposure, directly demonstrating that this scaffold can cross the BBB.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "A primary carboxamide analogue with a dichlorophenyl group achieved a CSF:free ratio of 1:1 in rats, showing that the primary amide in the query does not prevent excellent CNS penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "AH-7921, a close dichlorobenzamide analogue, showed a brain-to-plasma ratio of 16.6 in rats, indicating strong brain uptake for this structural family.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "A primary sulfonamide analogue also achieved a CSF:free ratio of 1:1 in rats, reinforcing that polar amide/sulfonamide substituents on dichlorophenyl cycloalkane scaffolds are CNS-penetrant.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "A lower-similarity piperazine-containing analogue showed low brain exposure in NHP PET (SUVpeak 0.4), but its additional polar/ionizable groups limit transfer to the neutral dicarboxamide query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Multiple close analogues with the same dichlorophenyl-cyclohexane amide scaffold show direct brain penetration, high brain-to-plasma ratios, or CSF:free ratios of 1:1; the query's neutral primary amide/anilide is consistent with these CNS-penetrant phenotypes. Poorer-penetrant analogues contain ionizable acids or piperazine groups not present in the query, so they do not override the supportive evidence.",
  "evidence_gaps": [
    "No direct brain or CSF measurement for the exact query molecule",
    "No P-gp/BCRP efflux data for the query",
    "Morgan similarities are moderate (0.25-0.37) rather than near-identical analogues",
    "No human pharmacokinetic data for the query"
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

